class _Chainable:
    """An object, where input and output configuration have to match when merged"""

    # every variable is derived as a subclass
    # every instance represents a certain entry in that class

    def __init__(
        self,
        input_config=None,
        output_config=None,
    ):
        self._inp_config = None
        self._out_config = None
        self.input_config = input_config
        self.output_config = output_config

    @property
    def config(self):
        """access config for fast access"""
        return (self.input_config, self.output_config)

    @property
    def input_config(self):
        """access read-only attribute input_config"""
        if self._inp_config is None:
            return None
        return self._inp_config()

    @input_config.setter
    def input_config(self, target):
        if target is None:
            inp_config = None
        else:
            inp_config = weakref.ref(target)
        self._inp_config = inp_config

    @property
    def output_config(self):
        """access read-only attribute output_config"""
        if self._out_config is None:
            return None
        return self._out_config()

    @output_config.setter
    def output_config(self, target):
        if target is None:
            out_config = None
        else:
            out_config = weakref.ref(target)
        self._out_config = out_config

    def combine(self, other):
        """combine two chainables"""
        if not _Chainable.is_compatible(self, other):
            raise ValueError("Incompatible Variables cannot be combined")
        return _Chainable(
            input_config=self.input_config, output_config=other.output_config
        )

    def __or__(self, other):
        return self.combine(other)

    @staticmethod
    def is_compatible(first, second):
        """check if the variables fit together"""
        if first.output_config is not None:
            if second.input_config is not None:
                if first.output_config != second.input_config:
                    return False
        return True

    def _get_config(self, config=None):
        """get the proper config or an error. External or inner or match or error"""
        if self.input_config is None:
            return config
        if config is None:
            return self.input_config
        if config == self.input_config:
            return config
        raise ValueError("Incompatible input configurations")


class InstructionVariable(_Chainable):
    """Instruction Variable is a chainable"""

    _name = "DEFAULT"
    _offset_handle = "AUTO"
    _default_config = None

    def __init__(
        self,
        *offsets,
        input_config=None,
        output_config=None,
        _pure_copy=False,
    ):
        if input_config is None:
            input_config = type(self)._default_config
        output_config = input_config
        super().__init__(
            input_config=input_config, output_config=output_config
        )
        self._offsets = []
        if _pure_copy:
            self._offsets = list(offsets)
        else:
            self.progress(*offsets)

    def __init_subclass__(cls, name=None, offset="AUTO", config=None):
        if name is None:
            name = cls.__name__
        cls._name = name
        if config is not None:
            cls._default_config = config
        cls._offset_handle = offset

    @classmethod
    def set_offset_handle(cls, offset_type="AUTO"):
        """set the offset handle"""
        cls._offset_handle = offset_type

    @classmethod
    def set_default_config(cls, config=None):
        """set the default config"""
        cls._default_config = config

    @classmethod
    def _new_bare(cls, name):
        if not isinstance(name, str):
            raise ValueError("Name must be a string")
        return type(name, (InstructionVariable,), {})

    @classmethod
    def new(cls, name, offset_type="AUTO", config=None):
        """generate a new class"""
        newclass = cls._new_bare(name)
        newclass.set_offset_handle(offset_type)
        newclass.set_default_config(config)
        return newclass

    def __str__(self):
        offset = (
            f"({':'.join(map(str, self.plain_offsets))})"
            if self.plain_offsets
            else "O"
        )
        return f"<{self.name}@{offset}>"

    def __repr__(self):
        return str(self)
        # return f"<{self._name}>"

    def copy(self):
        """get a copy. Does what it says, nothing special."""
        return type(self)(
            *self.plain_offsets,
            input_config=self.input_config,
            output_config=self.output_config,
        )

    @property
    def name(self):
        """access offsets"""
        return self._name

    @property
    def plain_offsets(self):
        """access offsets"""
        return list(self._offsets)

    @property
    def offsets(self):
        """access offsets"""
        return list(self.evaluate())

    def evaluate(self):
        """evaluate the offsets"""
        current_pointer = self.input_config
        for offset in self._offsets:
            if current_pointer is not None and offset.input_config is not None:
                if current_pointer != offset.input_config:
                    raise ValueError("Found incompatible offsets")
            offset, new_pointer = offset.compute(current_pointer)
            yield offset
            current_pointer = new_pointer

    def progress(self, *offsets):
        """append an extra offset"""
        # print("progress called with offsets", offsets)
        for offset in offsets:
            if not isinstance(offset, InstructionVariableOffset):
                offset = self._auto_convert(offset)
            # print("types:", type(self), type(offset))
            # print("configs:", self.input_config, self.output_config)
            if not _Chainable.is_compatible(self, offset):
                # print("here's the problem:", offset, self)
                raise ValueError("Incompatible offsets cannot be combined")
            self._offsets.append(offset)
            self.output_config = offset.output_config
        return self

    def _auto_convert(self, potential_offset):
        if isinstance(potential_offset, InstructionVariableOffset):
            return potential_offset
        return InstructionVariableOffset.auto_convert(
            potential_offset,
            type(self)._offset_handle,
            self.output_config,
        )

    def progressed(self, *offsets):
        """get a new instance with extra offsets"""
        return type(self)(
            *self.plain_offsets,
            input_config=self.input_config,
            output_config=self.output_config,
            _pure_copy=True,
        ).progress(*offsets)

    def merge(self, other):
        """merge an instruction variable with another one"""
        if not isinstance(other, InstructionVariable):
            raise TypeError("Merging partner must be an InstructionVariable")
        if not _Chainable.is_compatible(self, other):
            raise ValueError("Incompatible variables cannot be combined")
        # print("merge var", self, other)
        return type(self)(
            *self.plain_offsets,
            *other.plain_offsets,
            input_config=self.input_config,
            output_config=other.output_config,
            _pure_copy=True,
        )
        # print("result", ret)
        # return ret

    def __add__(self, other):
        if not isinstance(other, InstructionVariableOffset):
            raise TypeError("Offset must be an InstructionVariableOffset")
        return self.progressed(other)

    def __or__(self, other):
        return self.merge(other)


class InstructionVariableOffset(_Chainable):
    """
    The offset is treated individually
    """

    def __init__(self, value, input_config=None, output_config=None):
        super().__init__(
            input_config=input_config, output_config=output_config
        )
        self._value = value
        # self._fixed_value = None

    def __str__(self):
        return f"+{self._value}"

    def __repr__(self):
        return f"+{self._value}"

    @staticmethod
    def auto_convert(potential_offset, handle="AUTO", config=None):
        """automatically convert the offset using the identifier handle"""
        # print("auto_convert was called")
        if isinstance(potential_offset, InstructionVariableOffset):
            return potential_offset
        match handle.upper().strip():
            case "AUTO":
                if isinstance(potential_offset, int):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="int", config=config
                    )
                if isinstance(potential_offset, str):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="key", config=config
                    )
                if isinstance(potential_offset, tuple):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="key", config=config
                    )
                if isinstance(potential_offset, InstructionVariable):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="symbol", config=config
                    )
                raise TypeError(
                    f"Cannot interpret offset type from {potential_offset}."
                )
            case "KEY":
                return KeyOffset(potential_offset, keymap=config)
            case "SYMBOL":
                return SymbolicOffset(potential_offset, input_config=config)
            case "INT":
                return IntegerOffset(potential_offset, input_config=config)
            case _:
                raise KeyError(f"Unknown offset handle: {handle}")

    def compute(self, config):
        """compute the offset from the input value"""
        raise NotImplementedError("Subclass must implement this method.")

    # def fix(self, config=None):
    #     """fix the value"""
    #     self._fixed_value, output_config = self.compute(config=config)
    #     if output_config is not None:
    #         self.output_config = output_config
    #     return self._fixed_value

    def evaluate(
        self,
        config=None,
        # fix=True,
    ):
        """get the actual offset. This might trigger the computation"""
        # if fix:
        #     return self.fix(config=config)
        offset, _ = self.compute(config=config)
        return offset


class KeyOffset(InstructionVariableOffset):
    """
    An offset made from a key in a keymap
    """

    def __init__(self, key, keymap=None, out_config=None):
        if keymap is not None:
            if key not in keymap:
                raise KeyError(f"Key '{key}' not found in keymap {keymap}")
            out_config = keymap[key]
        super().__init__(
            value=key, input_config=keymap, output_config=out_config
        )

    def compute(self, config=None):
        current_pointer = self._get_config(config=config)
        assert current_pointer is not None, config
        offset, new_pointer = current_pointer.goto(self._value)
        return offset, new_pointer


class IntegerOffset(InstructionVariableOffset):
    """
    An offset simply made by an integer
    """

    def compute(self, config=None):
        """simply get the prepared value"""
        return self._value, self.output_config


class StringOffset(InstructionVariableOffset):
    """
    An offset that has a string based value
    """

    def __init__(self, expression, input_config=None, output_config=None):
        super().__init__(
            expression, input_config=input_config, output_config=output_config
        )

    def replace_expression(self, expression):
        """associate a new value"""
        self._value = expression

    def compute(self, config=None):
        """stringify whatever enters"""
        # this might change once I have completely implemented RoutineVariables
        return str(self._value), self.output_config


class SymbolicOffset(InstructionVariableOffset):
    """
    An purely symbolical offset that has a value to be determined later.

    Note: maybe SymbolicOffsets are not needed anyways, as it could be strings
    with the proper expressions right away upon their definition. Let's see.

    Note: Instead of symbolic environments I suggest symbolic offsets, so all
    the internals of enviroments can work as expected, including the stacking,
    dict-like access routines and more.
    """

    def __init__(self, origin, input_config=None, output_config=None):
        super().__init__(
            None, input_config=input_config, output_config=output_config
        )
        self._origin = origin

    def substitute(self, value):
        """substitute a value for the placeholder"""
        if not isinstance(value, str):
            value = str(value)
        self._value = value

    def compute(self, config=None):
        """stringify whatever enters"""
        # this might change once I have completely implemented RoutineVariables
        if self._value is None:
            return self._origin, self.output_config
            # return "?", self.output_config
        return self._value, self.output_config


class InstructionEnvironment:
    """Defines an instruction environment where all known variables can be stored"""

    def __init__(self, variables=None):
        if variables is None:
            variables = {}
        self._variables: Dict[type, InstructionVariable] = variables

    def items(self):
        """iterate through dict-like items"""
        yield from self._variables.items()

    def as_dict(self):
        """display as a dictionary"""
        return {key: val for key, val in self.items()}

    def copy(self, **_) -> InstructionEnvironment:
        """make a proper copy"""
        copied = type(self)()
        for key, variable in self.items():
            copied.update(key, variable.copy())
        return copied

    def deepcopy(self, memo=None, **kwargs):
        """deepcopy implementation"""
        if memo is None:
            memo = {}
        return self.__deepcopy__(memo=memo, **kwargs)

    def __deepcopy__(self, memo=None, **kwargs):
        if memo is None:
            memo = {}
        if id(self) in memo:
            return id(self)
        copied = self.copy(**kwargs)
        memo[id(self)] = copied
        return copied

    def __str__(self):
        content_as_string = [
            f"{val}:<{src._name}*?*>" for src, val in self._variables.items()
        ]
        return f"<Env{content_as_string}>"

    def merge(
        self, inner_environment: InstructionEnvironment
    ) -> InstructionEnvironment:
        """merge an environment with another. Creates a new object."""
        new_environment = self.copy()
        new_environment.include(inner_environment)
        return new_environment

    def include(self, inner_environment: InstructionEnvironment):
        """include an environment"""
        for inner_key, inner_variable in inner_environment.items():
            self.update(inner_key, inner_variable)
        return self

    def __or__(self, other: InstructionEnvironment) -> InstructionEnvironment:
        return self.merge(other)

    def delete(self, target_class):
        """delete the target class from the list of known variables"""
        if target_class in self:
            del self._variables[target_class]

    def update(self, inner_target_class, inner_variable):
        """
        update the internal dictionary. Extend if possible.
        set variable to None to delete from environment
        """
        if not issubclass(inner_target_class, InstructionVariable):
            raise TypeError(
                f"Key must be an InstructionVariable subclass: {inner_target_class}"
            )
        # the added variable could be subject to an already registered offset.
        # in this case, extend this offset and update the target class.
        if (existing_target_class := type(inner_variable)) in self:
            self._variables[inner_target_class] = self._variables[
                existing_target_class
            ].merge(inner_variable)
            # for now, remove the old offset.
            self.delete(existing_target_class)
            return self
        self._variables[inner_target_class] = inner_variable
        return self

    def keys(self):
        """access keys of inner dict"""
        return self._variables.keys()

    def __getitem__(self, key):
        return self._variables[key]

    def __contains__(self, key):
        return key in self._variables


